import heapq
import random

def euclidean_distance(v1, v2):
    return sum((a - b) ** 2 for a, b in zip(v1, v2)) ** 0.5

def knn_search(query, vectors, k):
    # maintain a heap of the best k candidates instead of sorting everything
    heap = []
    for i, v in enumerate(vectors):
        dist = euclidean_distance(query, v)
        # use negative distance since heapq is a min heap, but we want to keep smallest distances
        if len(heap) < k:
            heapq.heappush(heap, (-dist, i))
        elif -dist > heap[0][0]:
            heapq.heapreplace(heap, (-dist, i))
    return sorted([(i, -neg_dist) for neg_dist, i in heap], key=lambda x: x[1])

vectors = [[random.random() for _ in range(8)] for _ in range(1000)]
query = [random.random() for _ in range(8)]

for k in [1, 5, 20]:
    results = knn_search(query, vectors, k)
    print(f"K={k}: found {len(results)} neighbors")
    print(f"  closest distance: {results[0][1]:.4f}, farthest of the K: {results[-1][1]:.4f}")
